import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaBookMedical, FaPlusCircle, FaEdit, FaTrash, FaClock, FaLayerGroup } from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import AlertBox from "./AlertBox";
import AppShell from "./ui/AppShell";
import StatCard from "./ui/StatCard";
import Panel from "./ui/Panel";
import "./theme.css";

function TeacherDashboard() {
  const teacherId = localStorage.getItem("user_id");
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    subject_code: ""
  });

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);
  const [editCourseId, setEditCourseId] = useState(null);

  const fetchCourses = useCallback(async () => {
    try {
      const response = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = response.data.courses || [];

      const myCourses = allCourses.filter(
        (course) => String(course.teacher_id) === String(teacherId)
      );

      setCourses(myCourses);
    } catch (error) {
      console.error(error);
    }
  }, [teacherId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleEdit = (course) => {
    setFormData({
      title: course.title,
      description: course.description,
      subject_code: course.subject_code
    });
    setEditCourseId(course.id);
  };

  const handleDelete = async (courseId) => {
    try {
      const res = await axios.delete(`http://127.0.0.1:8000/delete-course/${courseId}`);
      setAlert({ message: res.data.message, type: "success" });
      fetchCourses();
    } catch (error) {
      console.error(error);
      setAlert({ message: "Course deletion failed", type: "error" });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...formData,
        teacher_id: parseInt(teacherId)
      };

      let res;
      if (editCourseId) {
        res = await axios.put(`http://127.0.0.1:8000/update-course/${editCourseId}`, payload);
      } else {
        res = await axios.post("http://127.0.0.1:8000/create-course", payload);
      }

      setAlert({ message: res.data.message, type: "success" });
      setFormData({ title: "", description: "", subject_code: "" });
      setEditCourseId(null);
      fetchCourses();
    } catch (error) {
      console.error(error);
      setAlert({ message: "Course save failed", type: "error" });
    }
  };

  const recentCourses = [...courses].slice(0, 3);
  const latestCourse = recentCourses[0];

  return (
    <AppShell
      title="Teacher Dashboard"
      subtitle="Create structured courses, manage recent additions, and control your teaching workspace."
      action={
        <button className="btn btn-primary" onClick={() => navigate("/courses")}>
          View All Courses
        </button>
      }
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-4" style={{ marginBottom: "18px" }}>
        <StatCard
          icon={<FaBookMedical />}
          label="Total Courses"
          value={courses.length}
          hint="All courses created by you"
        />
        <StatCard
          icon={<FaClock />}
          label="Recent Courses"
          value={recentCourses.length}
          hint="Showing latest 3 added"
          accent="var(--warning)"
        />
        <StatCard
          icon={<FaLayerGroup />}
          label="Current Mode"
          value="Teacher"
          hint="Content and course manager"
          accent="var(--info)"
        />
        <StatCard
          icon={<FaPlusCircle />}
          label="Latest Subject"
          value={latestCourse ? latestCourse.subject_code : "N/A"}
          hint={latestCourse ? latestCourse.title : "No courses yet"}
          accent="var(--success)"
        />
      </div>

      <div className="page-grid-2" style={{ marginBottom: "18px" }}>
        <Panel title={editCourseId ? "Edit Course" : "Create New Course"}>
          <form onSubmit={handleSubmit}>
            <input
              className="input"
              type="text"
              name="title"
              placeholder="Course Title"
              value={formData.title}
              onChange={handleChange}
            />

            <textarea
              className="textarea"
              name="description"
              placeholder="Course Description"
              value={formData.description}
              onChange={handleChange}
            />

            <input
              className="input"
              type="text"
              name="subject_code"
              placeholder="Subject Code"
              value={formData.subject_code}
              onChange={handleChange}
            />

            <div className="btn-row">
              <button className="btn btn-primary" type="submit">
                {editCourseId ? "Update Course" : "Add Course"}
              </button>

              {editCourseId && (
                <button
                  className="btn btn-secondary"
                  type="button"
                  onClick={() => {
                    setEditCourseId(null);
                    setFormData({
                      title: "",
                      description: "",
                      subject_code: ""
                    });
                  }}
                >
                  Cancel Edit
                </button>
              )}
            </div>
          </form>
        </Panel>

        <Panel title="Teaching Overview">
          <div className="list-card">
            <h4 style={{ marginTop: 0 }}>Quick Guidance</h4>
            <div className="muted" style={{ lineHeight: 1.7 }}>
              Add only structured courses with clear subject codes. Keep descriptions concise
              and consistent so quizzes, assignments, materials, and smart planning all map properly.
            </div>
          </div>

          <div className="list-card">
            <h4 style={{ marginTop: 0 }}>Best Practice</h4>
            <div className="muted" style={{ lineHeight: 1.7 }}>
              Use one subject code per course, then attach quiz, assignments, notes, and analytics
              around the same course flow.
            </div>
          </div>
        </Panel>
      </div>

      <Panel
        title="Recent Added Courses"
        action={
          <button className="btn btn-secondary" onClick={() => navigate("/courses")}>
            View All
          </button>
        }
      >
        {recentCourses.length === 0 ? (
          <p className="muted">No recent courses found.</p>
        ) : (
          <div className="page-grid-3">
            {recentCourses.map((course) => (
              <div
                key={course.id}
                style={{
                  background: "var(--surface)",
                  border: "1px solid var(--border)",
                  borderRadius: "18px",
                  padding: "18px",
                  boxShadow: "var(--shadow-sm)"
                }}
              >
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    gap: "10px",
                    alignItems: "center"
                  }}
                >
                  <h4 style={{ margin: 0 }}>{course.title}</h4>
                  <span className="badge badge-purple">{course.subject_code}</span>
                </div>

                <div className="muted" style={{ marginTop: "10px", lineHeight: 1.6 }}>
                  {course.description}
                </div>

                <div className="muted" style={{ marginTop: "10px" }}>
                  Created By: {course.created_by || "You"}
                </div>

                <div className="muted" style={{ marginTop: "6px" }}>
                  Created At:{" "}
                  {course.created_at
                    ? new Date(course.created_at).toLocaleString()
                    : "N/A"}
                </div>

                <div className="btn-row" style={{ marginTop: "14px" }}>
                  <button className="btn btn-info" onClick={() => handleEdit(course)}>
                    <FaEdit style={{ marginRight: 6 }} />
                    Edit
                  </button>

                  <button className="btn btn-danger" onClick={() => handleDelete(course.id)}>
                    <FaTrash style={{ marginRight: 6 }} />
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </Panel>
    </AppShell>
  );
}

export default TeacherDashboard;
